let C=null, INS=[]; const CH={}; const tipFn=(x,y,t,items)=>showTip(x,y,t,items);
const sevCls = s => s==='good'?'good':s==='bad'?'bad':s==='warn'?'warn':'';
const ICO={alert:'<circle cx="12" cy="12" r="9.5"/><path d="M12 7.5v5M12 16.5v.01"/>',tri:'<path d="M10.3 3.9 1.9 18a2 2 0 0 0 1.7 3h16.8a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9.5v4M12 17v.01"/>',up:'<path d="m22 7-8.5 8.5-5-5L2 17"/><path d="M16 7h6v6"/>',info:'<circle cx="12" cy="12" r="9.5"/><path d="M12 16.5v-5M12 7.5v.01"/>',clock:'<circle cx="12" cy="12" r="9.5"/><path d="M12 6.5V12l3.5 2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2.5 12h2M19.5 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',cal:'<rect x="3.5" y="4.5" width="17" height="16" rx="2"/><path d="M8 2.5v4M16 2.5v4M3.5 10h17"/>',target:'<circle cx="12" cy="12" r="9.5"/><circle cx="12" cy="12" r="5.5"/><circle cx="12" cy="12" r="1.5"/>',pen:'<path d="M12 20h8.5"/><path d="M16.5 3.6a2.1 2.1 0 0 1 3 3L7.5 18.6l-4 .9.9-4z"/>'}, IC_GLYPH={'!':'alert','△':'tri','↑':'up','•':'info','◷':'clock','☀':'sun','📅':'cal','🎯':'target','✎':'pen'}; const icSvg=(ic,cls)=>`<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICO[ICO[ic]?ic:IC_GLYPH[ic]||(cls==='bad'?'alert':cls==='warn'?'tri':cls==='good'?'up':'info')]}</svg>`; const calloutX=(cls,ic,title,body,act,imp)=>`<div class="callout ${cls}"><div class="ic">${icSvg(ic,cls)}</div><div class="cx">${imp?`<span class="imp">${imp}</span>`:''}<b class="ct">${title}</b>${body?`<p class="cb">${String(body).replace(/^[a-z]/,c=>c.toUpperCase())}</p>`:''}${act?`<span class="act"><b>Action:</b> ${act}</span>`:''}</div></div>`; const callSplit=t=>{ t=String(t); const cap=s=>s.replace(/^[a-z]/,c=>c.toUpperCase()), m=/^\s*<b>([^<]*)<\/b>\s*(?:—|:)\s+/.exec(t); if(m) return [m[1],cap(t.slice(m[0].length))]; let tag=0, sep=-1, dot=-1; for(let k=0;k<t.length&&dot<0;k++){ const ch=t[k]; if(ch==='<') tag=1; else if(ch==='>') tag=0; else if(!tag&&t[k+1]===' '){ if(sep<0&&(ch===':'||(ch==='—'&&t[k-1]===' '))) sep=k; else if(ch==='.') dot=k; } } if(sep>0&&t.slice(0,sep).replace(/<[^>]*>/g,'').length<=100) return [t.slice(0,sep).trim(),cap(t.slice(sep+1).trim())]; if(dot>0&&dot<t.length-2) return [t.slice(0,dot+1),t.slice(dot+2)]; return [t,'']; }; const callout=(cls,ic,t,act,imp)=>{ const [a,b]=callSplit(t); return calloutX(cls,ic,a,b,act,imp); }; // glyph/emoji icons become 16px line icons (numbers follow the severity); the title gets its own .ct line: '<b>T</b> — body', 'Label: body', 'X — body' or the first sentence
const SEVL={good:'Strength',bad:'Risk',warn:'Watch'}; const insCallout = (x,_i,_a,pre) => calloutX(sevCls(x.sev), '', esc(x.title), x.text, x.action, (pre?pre+' · ':'')+(SEVL[x.sev]||'Insight')); const clipMore=(el,n,np=n)=>{ if(!el) return; const nx=el.nextElementSibling; if(nx&&nx.classList.contains('more-row')) nx.remove(); const kids=[...el.children], rows=kids.filter(c=>!c.classList.contains('attn-h')), hd=Math.max(0,rows.length-n), hp=Math.max(0,rows.length-np), open=el.dataset.open==='1'; el.dataset.n=n; kids.forEach(c=>{ const k=rows.indexOf(c.classList.contains('attn-h')?c.nextElementSibling:c); c.classList.toggle('cx',k>=n); c.classList.toggle('cxp',k>=np); }); el.classList.toggle('clip',!!(hd||hp)&&!open); if(!hd&&!hp) return; el.insertAdjacentHTML('afterend',`<div class="more-row${hd?'':' ph-only'}"><button type="button" class="text-button show-more" aria-expanded="${open}"${el.id?` aria-controls="${el.id}"`:''}>${open?'Show less':`<span class="sm-d">Show ${hd} more</span><span class="sm-p">Show ${hp} more</span>`}</button></div>`); el.nextElementSibling.firstChild.addEventListener('click',()=>{ el.dataset.open=open?'':'1'; clipMore(el,n,np); if(open) el.scrollIntoView({block:'nearest'}); }); }; // long lists show n rows (np at 600px and below) plus a 'Show N more' toggle
function fig(id){ return document.getElementById(id); }
function chart(id, fn, opts){ if(opts&&opts.empty){ const e=fig(id), q=CH[id]; if(q&&q.destroy) try{ q.destroy(); }catch(x){} CH[id]=null; if(e) e.innerHTML=`<div class="panel-meta chart-empty">${opts.empty}</div>`; return null; } /* opts.empty: a one-line empty state instead of a bare axis */ if(chart._tab!==state.tab){ chart._tab=state.tab; chart._visit=(chart._visit||0)+1; } const el=fig(id), pv=CH[id], upd=!!(el&&pv&&pv._fn===fn&&pv._visit===chart._visit&&!el._anims&&el.querySelector(':scope > svg')); if(pv&&pv.destroy&&!upd) try{ pv.destroy(); }catch(e){} if(!el) return null; const o={height:240, tip:showTip, hideTip, update:upd, ...opts}; try{ CH[id]=Charts[fn](el,o); if(CH[id]){ CH[id]._fn=fn; CH[id]._visit=chart._visit; } deferAnims(el); let lg=el.nextElementSibling; while(lg&&lg.classList.contains('tvwrap')) lg=lg.nextElementSibling; if(CH[id]&&CH[id].series&&lg&&lg.classList.contains('legend')&&window.ChartsLegend) ChartsLegend(lg,CH[id].series); }catch(e){ console.error('chart',id,e); el.innerHTML=`<div class="panel-meta">Chart unavailable: ${esc(e.message)}</div>`; CH[id]=null; } return CH[id]; }
function toggleTable(id){ const el=fig(id); if(!el) return; let w=el.parentElement.querySelector('.tvwrap[data-for="'+id+'"]'); if(w){ w.remove(); return; } const ch=CH[id]; if(!ch||!ch.tableView) return; const rows=ch.tableView(); const t=document.createElement('table'); t.className='data-table'; rows.forEach((r,i)=>{ const tr=document.createElement('tr'); for(const v of r){ const c=document.createElement(i?'td':'th'); if(!i) c.className='nosort'; c.textContent=v; tr.appendChild(c);} t.appendChild(tr); }); w=document.createElement('div'); w.className='table-wrap tvwrap'; w.dataset.for=id; w.style.maxHeight='260px'; w.style.marginTop='10px'; w.appendChild(t); el.insertAdjacentElement('afterend', w); }
function countTo(el, v, f){ if(!el) return; if(typeof v==='number'&&isFinite(v)) morphNum(el, v, f, 700); else el.textContent=f(v); }
const VIEWS={exec:renderExec, om:renderOM, leader:renderLeader, agents:renderAgents, calls:renderCalls, insights:renderInsights, data:renderQuality};
/* a render started by a press (click/change/input/keydown) waits one painted frame so the pressed state and body.busy show first; programmatic calls (tests, setPreset from code) stay synchronous */
let RA_RAF=0, RA_TO=0; function renderAll(){ const ev=window.event; if(ev&&ev.isTrusted&&/^(click|change|input|keydown)$/.test(ev.type)&&window.requestAnimationFrame){ document.body.classList.add('busy'); cancelAnimationFrame(RA_RAF); clearTimeout(RA_TO); RA_RAF=requestAnimationFrame(()=>{ RA_TO=setTimeout(renderNow,0); }); return; } renderNow(); }
function renderNow(){ cancelAnimationFrame(RA_RAF); clearTimeout(RA_TO); try{ C=extendCompute(compute()); INS=insightsFor(C);
  const sc=[state.om==='All'?'all managers':state.om, state.tl==='All'?'all teams':state.tl, state.phase==='All'?'all phases':state.phase, state.tenure==='All'?'all tenure buckets':'tenure '+state.tenure].join(' · ');
  document.getElementById('scopeText').textContent=`${sc} · ${n0(C.hcScope)} agents`; document.getElementById('periodLabel').textContent=`${fdl(state.from)} – ${fdl(state.to)}`;
  document.getElementById('footScope').textContent=`Scope: ${sc} · ${state.exdup?'duplicates excluded':'duplicates included'} · prior period ${fds(DATES[Math.max(0,C.p0)])} – ${fds(DATES[Math.max(0,C.p1)])}`; document.getElementById('footData').textContent=`Data through ${fdl(META.maxDate)} · ${n0(rows.length)} entries`;
  renderHero(); (VIEWS[state.tab]||renderExec)(); armReveals(); } finally { requestAnimationFrame(()=>document.body.classList.remove('busy')); } }

